@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Plus+Jakarta+Sans:wght@500;600;700&display=swap');

:root {
  --primary: #4F46E5;      /* Indigo 600 */
  --primary-hover: #4338CA;
  --primary-light: #EEF2FF;
  --accent: #FF613D;       /* Accent Orange */
  --accent-hover: #EA5332;
  --text-dark: #292A2E;
  --text-body: #4B5563;
  --text-light: #6B7280;
  --bg-white: #FFFFFF;
  --bg-light: #F8FAFC;
  --bg-dark: #0F172A;
  --border: #E2E8F0;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-glow: 0 0 20px rgba(79, 70, 229, 0.2);
  --transition: 0.2s ease-in-out;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', sans-serif;
  color: var(--text-body);
  background-color: var(--bg-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  color: var(--text-dark);
  line-height: 1.2;
  font-weight: 700;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 4vw, 3rem); letter-spacing: -0.01em; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

a {
  color: var(--primary);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--primary-hover);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Utilities */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.text-center { text-align: center; }
.mt-1 { margin-top: 0.25rem; }
.mt-2 { margin-top: 0.5rem; }
.mt-4 { margin-top: 1rem; }
.mt-8 { margin-top: 2rem; }
.mt-12 { margin-top: 3rem; }
.mt-16 { margin-top: 4rem; }
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-8 { margin-bottom: 2rem; }
.mb-16 { margin-bottom: 4rem; }
.pt-16 { padding-top: 4rem; }
.pb-16 { padding-bottom: 4rem; }
.pt-24 { padding-top: 6rem; }
.pb-24 { padding-bottom: 6rem; }
.py-16 { padding-top: 4rem; padding-bottom: 4rem; }
.py-24 { padding-top: 6rem; padding-bottom: 6rem; }

.bg-light { background-color: var(--bg-light); }
.bg-dark { background-color: var(--bg-dark); color: white; }
.bg-dark h2, .bg-dark h3, .bg-dark p { color: white; }
.text-accent { color: var(--accent); }
.text-primary { color: var(--primary); }

.gradient-text {
  background: linear-gradient(135deg, var(--primary), var(--accent));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: all var(--transition);
  border: none;
  text-decoration: none;
}

.btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.btn-primary {
  background-color: var(--primary);
  color: white;
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  color: white;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background-color: var(--accent);
  color: white;
  box-shadow: var(--shadow-sm);
}

.btn-accent:hover {
  background-color: var(--accent-hover);
  color: white;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background-color: transparent;
  color: var(--text-dark);
  border: 1px solid var(--border);
}

.btn-outline:hover {
  border-color: var(--text-dark);
  color: var(--text-dark);
  background-color: var(--bg-light);
}

.btn-light {
  background-color: rgba(255, 255, 255, 0.1);
  color: white;
  backdrop-filter: blur(8px);
}

.btn-light:hover {
  background-color: rgba(255, 255, 255, 0.2);
  color: white;
}

/* Badge */
.badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  background-color: var(--primary-light);
  color: var(--primary);
  margin-bottom: 1rem;
}

/* Navigation */
.navbar {
  position: sticky;
  top: 0;
  z-index: 50;
  background-color: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
  padding: 16px 0;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.nav-logo {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-links {
  display: flex;
  gap: 32px;
  align-items: center;
}

.nav-link {
  color: var(--text-dark);
  font-weight: 500;
}

.nav-link:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  gap: 16px;
  align-items: center;
}

/* Hero Section */
.hero {
  padding: 100px 0;
  text-align: center;
  background: radial-gradient(circle at top center, var(--primary-light) 0%, white 100%);
  overflow: hidden;
}

.hero p {
  font-size: 1.25rem;
  color: var(--text-body);
  max-width: 600px;
  margin: 1.5rem auto 2.5rem;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
}

.hero-visual {
  margin-top: 60px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg), var(--shadow-glow);
  background: white;
  padding: 8px;
  border: 1px solid var(--border);
  overflow: hidden;
}

.hero-visual img {
  border-radius: var(--radius-md);
  width: 100%;
}

/* Logo Bar */
.logo-bar {
  padding: 40px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  background: white;
  text-align: center;
}

.logo-bar p {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 24px;
}

.logos {
  display: flex;
  justify-content: center;
  gap: 40px;
  flex-wrap: wrap;
  align-items: center;
  opacity: 0.6;
}

.logos span {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-dark);
}

/* Grids */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 40px; align-items: center; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }

/* Cards */
.card {
  background: white;
  padding: 32px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: transform var(--transition), box-shadow var(--transition);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.card-icon {
  width: 48px;
  height: 48px;
  background-color: var(--primary-light);
  color: var(--primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}

.card-icon svg { width: 24px; height: 24px; }

/* Feature Section Layout */
.feature-row { margin-bottom: 100px; }
.feature-row:nth-child(even) .feature-content { order: 2; }
.feature-row:nth-child(even) .feature-visual { order: 1; }

.feature-visual {
  background: var(--bg-light);
  border-radius: var(--radius-lg);
  padding: 40px;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

/* List styles */
.feature-list { list-style: none; margin-top: 1.5rem; }
.feature-list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 16px;
}
.feature-list li::before {
  content: '✓';
  color: var(--primary);
  font-weight: bold;
  background: var(--primary-light);
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

/* Pricing Page */
.pricing-toggle {
  display: inline-flex;
  background: var(--bg-light);
  padding: 4px;
  border-radius: var(--radius-full);
  margin-bottom: 40px;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--border);
}

.toggle-btn {
  padding: 8px 16px;
  border-radius: var(--radius-full);
  border: none;
  background: transparent;
  font-weight: 600;
  cursor: pointer;
  color: var(--text-light);
  transition: var(--transition);
}

.toggle-btn.active {
  background: white;
  color: var(--text-dark);
  box-shadow: var(--shadow-sm);
}

.save-badge {
  background: var(--accent);
  color: white;
  font-size: 0.75rem;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  font-weight: 700;
}

.plan-card {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.plan-header { margin-bottom: 24px; }
.plan-name { font-size: 1.25rem; font-weight: 700; margin-bottom: 8px; }
.plan-price { font-size: 2.5rem; font-weight: 700; color: var(--text-dark); }
.plan-price span { font-size: 1rem; color: var(--text-light); font-weight: 400; }
.plan-features { margin-top: 32px; flex-grow: 1; }
.plan-cta { margin-top: 32px; width: 100%; }

.plan-card.popular {
  border: 2px solid var(--primary);
  position: relative;
  transform: scale(1.02);
}

.plan-card.popular .popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-full);
}

/* Table */
.comparison-table { width: 100%; border-collapse: collapse; margin-top: 60px; }
.comparison-table th, .comparison-table td {
  padding: 16px;
  border-bottom: 1px solid var(--border);
  text-align: left;
}
.comparison-table th { background: var(--bg-light); font-weight: 600; color: var(--text-dark); }
.comparison-table th:first-child { border-top-left-radius: var(--radius-md); }
.comparison-table th:last-child { border-top-right-radius: var(--radius-md); }
.table-feature { font-weight: 500; color: var(--text-dark); }

/* Accordion FAQ */
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: transparent;
  border: none;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-dark);
  cursor: pointer;
  text-align: left;
}
.faq-answer {
  padding-bottom: 24px;
  color: var(--text-body);
  display: none;
}
.faq-item.active .faq-answer { display: block; }
.faq-item.active .faq-icon { transform: rotate(45deg); }

/* Testimonials */
.testimonial-card {
  background: var(--bg-light);
  padding: 32px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
}

.testimonial-text {
  font-size: 1.125rem;
  font-style: italic;
  margin-bottom: 24px;
  color: var(--text-dark);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 16px;
}

.author-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--primary-light);
}

.author-info strong { display: block; color: var(--text-dark); }
.author-info span { font-size: 0.875rem; color: var(--text-light); }

/* Forms (Login/Signup) */
.auth-layout {
  display: flex;
  min-height: 100vh;
}

.auth-form-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 40px;
}

.auth-form-inner {
  width: 100%;
  max-width: 400px;
}

.auth-sidebar {
  flex: 1;
  background: var(--bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  display: none; /* Mobile hidden */
}

@media (min-width: 768px) {
  .auth-sidebar { display: flex; }
}

.form-group { margin-bottom: 20px; }
.form-label { display: block; margin-bottom: 8px; font-weight: 500; color: var(--text-dark); }
.form-input {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 1rem;
  transition: border-color var(--transition);
}
.form-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px var(--primary-light);
}

.social-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: white;
  font-weight: 500;
  color: var(--text-dark);
  cursor: pointer;
  transition: background var(--transition);
  margin-bottom: 12px;
}
.social-btn:hover { background: var(--bg-light); }

.divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 24px 0;
  color: var(--text-light);
}
.divider::before, .divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--border);
}
.divider:not(:empty)::before { margin-right: 16px; }
.divider:not(:empty)::after { margin-left: 16px; }

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  background: white;
  padding: 24px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border);
  z-index: 100;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
}
@media (max-width: 768px) {
  .cookie-banner { flex-direction: column; text-align: center; }
  .cookie-actions { display: flex; flex-direction: column; width: 100%; gap: 12px; }
  .cookie-actions button { width: 100%; }
}

.cookie-modal {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 101;
  align-items: center;
  justify-content: center;
}
.cookie-modal.active { display: flex; }
.cookie-modal-content {
  background: white;
  padding: 32px;
  border-radius: var(--radius-lg);
  max-width: 500px;
  width: 90%;
}

.toggle-switch {
  position: relative;
  display: inline-block;
  width: 44px;
  height: 24px;
}
.toggle-switch input { opacity: 0; width: 0; height: 0; }
.toggle-slider {
  position: absolute;
  cursor: pointer;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: #ccc;
  transition: .4s;
  border-radius: 24px;
}
.toggle-slider:before {
  position: absolute;
  content: "";
  height: 18px; width: 18px;
  left: 3px; bottom: 3px;
  background-color: white;
  transition: .4s;
  border-radius: 50%;
}
input:checked + .toggle-slider { background-color: var(--primary); }
input:checked + .toggle-slider:before { transform: translateX(20px); }

/* Footer */
.footer {
  background: var(--bg-light);
  padding: 80px 0 40px;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 60px;
}
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-brand { grid-column: span 2; }
}
@media (max-width: 768px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: span 1; }
}
.footer-col h4 { font-size: 1rem; margin-bottom: 20px; }
.footer-links { list-style: none; }
.footer-links li { margin-bottom: 12px; }
.footer-links a { color: var(--text-body); font-size: 0.875rem; }
.footer-links a:hover { color: var(--primary); }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 32px;
  border-top: 1px solid var(--border);
  font-size: 0.875rem;
  color: var(--text-light);
}

/* Responsive */
@media (max-width: 768px) {
  .nav-links, .nav-actions { display: none; } /* Mobile menu simplified */
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .feature-row:nth-child(even) .feature-content,
  .feature-row:nth-child(even) .feature-visual { order: initial; }
  .comparison-table { display: block; overflow-x: auto; }
}

document.addEventListener('DOMContentLoaded', () => {

  // 1. FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    if (question) {
      question.addEventListener('click', () => {
        const isActive = item.classList.contains('active');
        // Close all
        faqItems.forEach(i => i.classList.remove('active'));
        // Open clicked if it wasn't active
        if (!isActive) {
          item.classList.add('active');
        }
      });
    }
  });

  // 2. Pricing Toggle (Monthly / Annually)
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  const planPrices = document.querySelectorAll('.plan-price-value');

  // Prices map (data-monthly, data-annual)
  // Assuming HTML structure: <div class="plan-price">$<span class="plan-price-value" data-monthly="18" data-annual="15">18</span><span>/user/mo</span></div>

  toggleBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Update toggle buttons
      toggleBtns.forEach(b => b.classList.remove('active'));
      e.target.classList.add('active');

      const isAnnual = e.target.textContent.toLowerCase().includes('annual');

      // Update prices
      planPrices.forEach(priceEl => {
        const monthly = priceEl.getAttribute('data-monthly');
        const annual = priceEl.getAttribute('data-annual');
        if (monthly && annual) {
          priceEl.textContent = isAnnual ? annual : monthly;
        }
      });
    });
  });

  // 3. Team Size Slider
  const teamSlider = document.getElementById('teamSizeSlider');
  const teamSizeValue = document.getElementById('teamSizeValue');

  if (teamSlider && teamSizeValue) {
    teamSlider.addEventListener('input', (e) => {
      teamSizeValue.textContent = e.target.value;
      // Could add logic here to highlight a specific plan based on team size
    });
  }

  // 4. Comparison Table Expand
  const expandFeaturesBtns = document.querySelectorAll('.expand-features-btn');
  const comparisonTableSection = document.getElementById('comparison-table-section');

  expandFeaturesBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      if (comparisonTableSection) {
        comparisonTableSection.style.display = 'block';
        comparisonTableSection.scrollIntoView({ behavior: 'smooth' });
      }
    });
  });

  // 5. Cookie Consent Banner
  const cookieBanner = document.getElementById('cookie-banner');
  const acceptCookiesBtn = document.getElementById('accept-cookies');
  const rejectCookiesBtn = document.getElementById('reject-cookies');
  const manageCookiesBtn = document.getElementById('manage-cookies');
  const cookieModal = document.getElementById('cookie-modal');
  const savePreferencesBtn = document.getElementById('save-preferences');

  if (cookieBanner && !localStorage.getItem('cookieConsent')) {
    cookieBanner.style.display = 'flex';
  }

  const dismissBanner = () => {
    if (cookieBanner) cookieBanner.style.display = 'none';
    localStorage.setItem('cookieConsent', 'true');
  };

  if (acceptCookiesBtn) acceptCookiesBtn.addEventListener('click', dismissBanner);
  if (rejectCookiesBtn) rejectCookiesBtn.addEventListener('click', dismissBanner);

  if (manageCookiesBtn && cookieModal) {
    manageCookiesBtn.addEventListener('click', () => {
      cookieModal.classList.add('active');
    });
  }

  if (savePreferencesBtn && cookieModal) {
    savePreferencesBtn.addEventListener('click', () => {
      cookieModal.classList.remove('active');
      dismissBanner();
    });
  }

  // 6. Forms (Login/Signup)
  const authForms = document.querySelectorAll('.auth-form');
  authForms.forEach(form => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      // Add visual feedback
      const btn = form.querySelector('button[type="submit"]');
      const originalText = btn.textContent;
      btn.textContent = 'Processing...';
      btn.disabled = true;

      setTimeout(() => {
        btn.textContent = originalText;
        btn.disabled = false;
        // Redirect logic would go here
        console.log('Form submitted');
      }, 1000);
    });
  });

});
